# -*- coding: utf-8 -*-
"""Builds the full, clean text of the reworked SANG Charter in docx and md formats."""
import os, sys
from docx import Document
from docx.shared import Pt, Inches, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

HERE = os.path.dirname(os.path.abspath(__file__))
OUT_DIR = os.environ.get('ACT_OUT_DIR') or os.path.join(HERE, '..', 'Законопроекты')

doc = Document()

# Set standard margins 2cm
sections = doc.sections
for s in sections:
    s.top_margin = Inches(0.75)
    s.bottom_margin = Inches(0.75)
    s.left_margin = Inches(0.85)
    s.right_margin = Inches(0.85)

def add_p(doc, text="", bold=False, italic=False, size=11, align=WD_ALIGN_PARAGRAPH.LEFT, space_before=0, space_after=3, color='000000'):
    p = doc.add_paragraph()
    p.alignment = align
    p.paragraph_format.space_before = Pt(space_before)
    p.paragraph_format.space_after = Pt(space_after)
    p.paragraph_format.line_spacing = 1.15
    if text:
        r = p.add_run(text)
        r.font.name = 'Times New Roman'
        r.font.size = Pt(size)
        r.bold = bold
        r.italic = italic
        r.font.color.rgb = RGBColor.from_string(color)
    return p

# Title Block
add_p(doc, "STATE OF SAN ANDREAS", bold=True, size=14, align=WD_ALIGN_PARAGRAPH.CENTER, space_before=0, space_after=2)
add_p(doc, "SAN-ANDREAS NATIONAL GUARD", bold=True, size=13, align=WD_ALIGN_PARAGRAPH.CENTER, space_before=0, space_after=4)
add_p(doc, "УСТАВ", bold=True, size=16, align=WD_ALIGN_PARAGRAPH.CENTER, space_before=6, space_after=2)
add_p(doc, "НАЦИОНАЛЬНОЙ ГВАРДИИ ШТАТА SAN-ANDREAS", bold=True, size=13, align=WD_ALIGN_PARAGRAPH.CENTER, space_before=0, space_after=6)
add_p(doc, "(Действующая редакция с изменениями, утверждёнными Офисом Генерального прокурора)", italic=True, size=10, align=WD_ALIGN_PARAGRAPH.CENTER, space_before=0, space_after=14, color='555555')

def add_h1(title):
    add_p(doc, title, bold=True, size=12, space_before=10, space_after=4)

def add_rule(num, text, sanctions=None):
    p = doc.add_paragraph()
    p.paragraph_format.space_before = Pt(2)
    p.paragraph_format.space_after = Pt(2)
    p.paragraph_format.line_spacing = 1.15
    r_num = p.add_run(num + " ")
    r_num.font.name = 'Times New Roman'
    r_num.font.size = Pt(11)
    r_num.bold = True
    r_text = p.add_run(text)
    r_text.font.name = 'Times New Roman'
    r_text.font.size = Pt(11)
    if sanctions:
        r_s = p.add_run(" | " + sanctions)
        r_s.font.name = 'Times New Roman'
        r_s.font.size = Pt(10.5)
        r_s.italic = True
        r_s.font.color.rgb = RGBColor.from_string('7F6000')

def add_body(text, italic=False):
    add_p(doc, text, italic=italic, size=10.5, space_before=1, space_after=2)

# --- Глава I
add_h1("Глава I. Общие положения")
add_rule("1.1.", "Устав San-Andreas National Guard (SANG) — это основной внутренний нормативный документ, регламентирующий организационное устройство, права, обязанности, ответственность и порядок несения воинской службы всеми военнослужащими Национальной Гвардии штата San-Andreas.")
add_rule("1.2.", "Любые изменения и дополнения в настоящий Устав вносятся Генералом SANG (General) или лицом, временно исполняющим его обязанности (ВрИО), и вступают в силу после обязательного утверждения Генеральным прокурором штата San-Andreas либо его заместителем в соответствии с действующим законодательством штата San-Andreas.")
add_rule("1.3.", "Военнослужащие SANG могут быть уволены со службы по следующим основаниям:")
add_body("• В связи с нарушением законодательства штата San-Andreas и/или действующего Устава SANG;\n• По собственному желанию;\n• В связи со служебным несоответствием занимаемой воинской должности по результатам аттестации;\n• За грубое нарушение воинской дисциплины либо отказ исполнять законный приказ командира (начальника);\n• В связи со вступлением в законную силу обвинительного приговора суда;\n• По законному мотивированному представлению Офиса Генерального прокурора штата San-Andreas;\n• В связи с истечением срока контракта о прохождении воинской службы.")
add_rule("1.4.", "Положения настоящего Устава являются общеобязательными для исполнения всеми военнослужащими SANG с момента издания приказа о зачислении на воинскую службу независимо от звания и занимаемой должности.")
add_rule("1.5.", "Несоблюдение настоящего Устава влечёт применение дисциплинарных взысканий: устный выговор, строгий выговор, внеочередная переаттестация, понижение в воинском звании, увольнение со службы, в зависимости от тяжести и характера проступка, кроме случаев, где конкретная санкция прямо закреплена в соответствующем пункте.")
add_rule("1.6.", "Применять дисциплинарные взыскания за нарушение Устава и законодательства имеют право: Генералитет SANG (в отношении всех военнослужащих), командиры и старший состав подразделений (в отношении личного состава своего подразделения), а также уполномоченные сотрудники подразделения Military Police (MP) (в отношении всех военнослужащих SANG в пределах предоставленных полномочий).")
add_rule("1.7.", "Военнослужащий не имеет права выполнять приказ командира (начальника), если данный приказ заведомо противоречит Конституции штата San-Andreas, законам штата или настоящему Уставу. О факте получения заведомо незаконного приказа военнослужащий обязан незамедлительно доложить в Military Police либо вышестоящему командованию.")
add_rule("1.8.", "Военнослужащие подразделения Military Police (MP) вправе проводить плановый личный обыск военнослужащих SANG и их служебного транспорта не чаще одного раза в неделю, а также внеплановый обыск при наличии обоснованных подозрений в незаконном обороте предметов — исключительно по согласованию с Генералом SANG или его заместителями в соответствии с действующим законодательством штата San-Andreas. Руководящий состав вправе производить личный обыск военнослужащих при их увольнении либо переводе в другую государственную структуру на предмет сдачи казённого вооружения, спецсредств и амуниции. Проведение обысков курсантов Академии сотрудниками MA или MCE не допускается; при необходимости обыск проводится сотрудниками MP.")
add_rule("1.9.", "Любой военнослужащий вправе зафиксировать и сообщить о совершённом правонарушении или нарушении воинской дисциплины в подразделение MP и руководящему составу при наличии видеофиксации. В случае совершения нарушения на территории Форта-Занкудо General и его заместители имеют право запросить и исследовать записи со стационарных камер видеонаблюдения военной базы.")
add_rule("1.10.", "Служебное время:")
