add_rule("6.1.", "Военнослужащим запрещено ношение вызывающих причесок (ирокезы, яркие неестественные цвета волос: красный, зеленый и т.п.).", "Устный")
add_rule("6.2.", "Длина прически военнослужащих мужского пола должна быть аккуратной и не опускаться ниже воротника кителя (рубашки). Исключение: военнослужащие женского пола (аккуратно собранные волосы).", "Устный")
add_rule("6.3.", "На служебной форме военнослужащего обязательно размещается именная нашивка, шеврон подразделения и знак различия воинского звания.", "Устный")
add_rule("6.4.", "Запрещено наличие татуировок на лице, шее и кистях рук, содержащих антигосударственную, нецензурную либо криминальную символику.", "Устный / Строгий")
add_rule("6.5.", "Запрещено ношение карнавальных масок, посторонних аксессуаров и предметов гражданской одежды в строю и при исполнении обязанностей.", "Устный / Строгий")
add_rule("6.6.", "Свободный (деловой) дресс-код разрешён исключительно Генералитету SANG и старшим офицерам при проведении официальных дипломатических и межведомственных встреч.", "Устный")
add_rule("6.7.", "Военнослужащие обязаны строго соблюдать требования Этического кодекса штата San-Andreas.", "Строгий / Увольнение")

# --- Глава VI
