# Also generate markdown version
md_lines = [
    "# УСТАВ НАЦИОНАЛЬНОЙ ГВАРДИИ ШТАТА SAN-ANDREAS",
    "## Действующая редакция с изменениями, утверждёнными Офисом Генерального прокурора\n",
    "> **Правовая основа:** Конституция штата San-Andreas (ст. 41 ч. 1), Закон «О Национальной Гвардии штата San-Andreas» (ст. 2, 5, 7, 7.1, 10, 25), Процессуальный кодекс штата San-Andreas (ст. 17.3, 18, 19, 32).\n",
]

for p in doc.paragraphs:
    t = p.text.strip()
    if not t: continue
    if t.startswith("Глава "):
        md_lines.append(f"\n### {t}\n")
    elif t.startswith("1.") or t.startswith("2.") or t.startswith("3.") or t.startswith("4.") or t.startswith("5.") or t.startswith("6.") or t.startswith("7.") or t.startswith("8.") or t.startswith("9.") or t.startswith("10.") or t.startswith("11.") or t.startswith("12.") or t.startswith("13.") or t.startswith("14.") or t.startswith("15."):
        md_lines.append(f"**{t}**\n")
    else:
        md_lines.append(f"{t}\n")

md_lines.append("\n---\n**УТВЕРЖДЕНО:** Генерал San-Andreas National Guard  \n**СОГЛАСОВАНО И УТВЕРЖДЕНО:** Генеральный прокурор штата San-Andreas (ст. 41 ч. 1 Конституции SA)")

md_path = os.path.join(OUT_DIR, "Устав SANG — Новая действующая редакция.md")
with open(md_path, 'w', encoding='utf-8') as f:
    f.write('\n'.join(md_lines))
print("Saved clean reworked Charter md:", md_path)
